import { useState, useEffect } from "react";
import { auth, db } from "./firebase";
import {
  signInWithEmailAndPassword,
  signOut,
  onAuthStateChanged,
} from "firebase/auth";
import {
  collection, doc, getDoc, addDoc, updateDoc, deleteDoc,
  query, where, onSnapshot, serverTimestamp,
} from "firebase/firestore";

// ─── TEMA ────────────────────────────────────────────────────────────────────
const P = "#d60006", S = "#005da8", WHITE = "#fff", LIGHT = "#f5f5f5", DARK = "#1a1a1a", GRAY = "#6b7280", BORDER = "#e5e7eb";

const css = {
  app: { fontFamily: "'Segoe UI',sans-serif", minHeight: "100vh", background: LIGHT, color: DARK },
  header: { background: P, color: WHITE, padding: "0 24px", display: "flex", alignItems: "center", justifyContent: "space-between", height: 60, boxShadow: "0 2px 8px rgba(0,0,0,.2)" },
  logo: { fontSize: 20, fontWeight: 700, letterSpacing: 1 },
  avatar: { width: 34, height: 34, borderRadius: "50%", background: WHITE, color: P, display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 700, fontSize: 14 },
  logoutBtn: { background: "rgba(255,255,255,.2)", border: "none", color: WHITE, padding: "6px 14px", borderRadius: 6, cursor: "pointer", fontSize: 13 },
  layout: { display: "flex", minHeight: "calc(100vh - 60px)" },
  sidebar: { width: 220, background: WHITE, borderRight: `1px solid ${BORDER}`, padding: "20px 0", display: "flex", flexDirection: "column" },
  navItem: a => ({ display: "flex", alignItems: "center", gap: 10, padding: "11px 20px", cursor: "pointer", fontSize: 14, fontWeight: a ? 600 : 400, color: a ? P : DARK, background: a ? "#fff0f0" : "transparent", borderLeft: a ? `3px solid ${P}` : "3px solid transparent" }),
  main: { flex: 1, padding: 28, overflowY: "auto" },
  pageTitle: { fontSize: 22, fontWeight: 700, marginBottom: 24 },
  card: { background: WHITE, borderRadius: 12, padding: 24, marginBottom: 20, boxShadow: "0 1px 4px rgba(0,0,0,.08)" },
  cardTitle: { fontSize: 16, fontWeight: 600, marginBottom: 16 },
  grid: n => ({ display: "grid", gridTemplateColumns: `repeat(${n},1fr)`, gap: 16 }),
  statCard: c => ({ background: c, borderRadius: 10, padding: "20px 24px", color: WHITE }),
  btn: v => ({ padding: "9px 20px", borderRadius: 8, border: "none", cursor: "pointer", fontSize: 14, fontWeight: 600, background: v === "primary" ? P : v === "secondary" ? S : "#e5e7eb", color: v === "primary" || v === "secondary" ? WHITE : DARK }),
  input: { width: "100%", padding: "9px 12px", borderRadius: 8, border: `1px solid ${BORDER}`, fontSize: 14, outline: "none", boxSizing: "border-box" },
  select: { width: "100%", padding: "9px 12px", borderRadius: 8, border: `1px solid ${BORDER}`, fontSize: 14, outline: "none", background: WHITE, boxSizing: "border-box" },
  label: { fontSize: 13, fontWeight: 500, color: GRAY, marginBottom: 5, display: "block" },
  fg: { marginBottom: 14 },
  table: { width: "100%", borderCollapse: "collapse", fontSize: 14 },
  th: { textAlign: "left", padding: "10px 12px", background: LIGHT, color: GRAY, fontWeight: 600, fontSize: 13, borderBottom: `1px solid ${BORDER}` },
  td: { padding: "10px 12px", borderBottom: `1px solid ${BORDER}` },
  badge: c => ({ display: "inline-block", padding: "3px 10px", borderRadius: 20, fontSize: 12, fontWeight: 600, background: c === "green" ? "#dcfce7" : c === "red" ? "#fee2e2" : c === "blue" ? "#dbeafe" : "#f3f4f6", color: c === "green" ? "#16a34a" : c === "red" ? "#dc2626" : c === "blue" ? "#1d4ed8" : GRAY }),
  tag: a => ({ padding: "5px 14px", borderRadius: 20, border: `1px solid ${a ? P : BORDER}`, background: a ? "#fff0f0" : WHITE, color: a ? P : GRAY, cursor: "pointer", fontSize: 13, fontWeight: a ? 600 : 400 }),
  alert: t => ({ padding: "12px 16px", borderRadius: 8, marginBottom: 16, fontSize: 14, background: t === "success" ? "#dcfce7" : t === "error" ? "#fee2e2" : "#dbeafe", color: t === "success" ? "#16a34a" : t === "error" ? "#dc2626" : "#1d4ed8" }),
  loginWrap: { minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center", background: `linear-gradient(135deg,${P},${S})` },
  loginCard: { background: WHITE, borderRadius: 16, padding: 40, width: 360, boxShadow: "0 8px 32px rgba(0,0,0,.18)" },
};

// ─── HELPERS ─────────────────────────────────────────────────────────────────
const toMins = t => { const [h, m] = t.split(":").map(Number); return h * 60 + m; };
const toHrs = m => { const h = Math.floor(Math.abs(m) / 60), mn = Math.abs(m) % 60; return `${h}h${mn > 0 ? mn + "m" : ""}`; };
const initials = n => n.split(" ").map(x => x[0]).join("").slice(0, 2).toUpperCase();
function calcExtra(entry, exit) {
  const s = toMins(entry), e = toMins(exit), total = e - s;
  let extra = 0;
  if (s < 480) extra += 480 - s;
  if (e > 1080) extra += e - 1080;
  return { total, normal: Math.max(total - extra, 0), extra };
}

function generatePDF(emp, records, projects, month, year) {
  const filtered = records.filter(r => {
    const [y, m] = r.date.split("-");
    return parseInt(y) === year && parseInt(m) === month;
  });
  let totalN = 0, totalE = 0;
  const rows = filtered.map(r => {
    const { normal, extra, total } = calcExtra(r.entry, r.exit);
    totalN += normal; totalE += extra;
    const proj = projects.find(p => p.id === r.projectId);
    return `<tr>
      <td>${r.date}</td><td>${r.entry}</td><td>${r.exit}</td>
      <td>${toHrs(total)}</td><td>${toHrs(normal)}</td>
      <td style="color:${extra > 0 ? "#d60006" : "#16a34a"};font-weight:600">${toHrs(extra)}</td>
      <td>${proj?.name || "-"}</td>
      <td>${r.location === "external" ? "Externo" : "Escritório"}</td>
    </tr>`;
  }).join("");
  const html = `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Relatório - ${emp.name}</title>
  <style>
    body{font-family:Arial,sans-serif;padding:32px;color:#1a1a1a}
    h1{color:#d60006}h2{color:#005da8;font-size:16px;margin-bottom:24px}
    .sum{display:flex;gap:20px;margin-bottom:24px}
    .s{border-radius:8px;padding:14px 22px;color:#fff;min-width:130px}
    .s1{background:#005da8}.s2{background:#d60006}.s3{background:#16a34a}
    .sn{font-size:26px;font-weight:700}.sl{font-size:12px;margin-top:2px}
    table{width:100%;border-collapse:collapse;font-size:13px}
    th{background:#f5f5f5;padding:9px 10px;text-align:left;border-bottom:2px solid #e5e7eb;color:#6b7280;font-size:12px}
    td{padding:9px 10px;border-bottom:1px solid #e5e7eb}
    .foot{margin-top:32px;font-size:12px;color:#6b7280;border-top:1px solid #e5e7eb;padding-top:12px}
  </style></head><body>
  <h1>Relatório Mensal de Horas</h1>
  <h2>${emp.name} — ${String(month).padStart(2, "0")}/${year}</h2>
  <div class="sum">
    <div class="s s1"><div class="sn">${filtered.length}</div><div class="sl">Dias Trabalhados</div></div>
    <div class="s s2"><div class="sn">${toHrs(totalE)}</div><div class="sl">Horas Extras</div></div>
    <div class="s s3"><div class="sn">${toHrs(totalN)}</div><div class="sl">Horas Normais</div></div>
  </div>
  <table><thead><tr>
    <th>Data</th><th>Entrada</th><th>Saída</th><th>Total</th><th>Normal</th><th>Extra</th><th>Projeto</th><th>Local</th>
  </tr></thead><tbody>${rows}</tbody></table>
  <div class="foot">Gerado em ${new Date().toLocaleDateString("pt-PT")} — TimeTrack</div>
  </body></html>`;
  const w = window.open("", "_blank");
  w.document.write(html);
  w.document.close();
  setTimeout(() => w.print(), 500);
}

