    setLoading(true); setErr("");
    try { await signInWithEmailAndPassword(auth, email, pass); }
    catch { setErr("Email ou senha incorretos."); }
    finally { setLoading(false); }
  };
  return (
    <div style={css.loginWrap}>
      <div style={css.loginCard}>
