function EmpRegister({ user, projects }) {
  const today = new Date().toISOString().split("T")[0];
  const [form, setForm] = useState({ date: today, entry: "", exit: "", location: "office", projectId: "", notes: "" });
  const [msg, setMsg] = useState(null);
  const [loading, setLoading] = useState(false);
  const active = projects.filter(p => p.status === "active");
  const save = async () => {
    if (!form.entry || !form.exit || !form.projectId) { setMsg({ type: "error", text: "Preencha todos os campos obrigatórios." }); return; }
    if (toMins(form.exit) <= toMins(form.entry)) { setMsg({ type: "error", text: "Saída deve ser depois da entrada." }); return; }
    setLoading(true);
    try {
      await addDoc(collection(db, "records"), { ...form, userId: user.uid, createdAt: serverTimestamp() });
      setMsg({ type: "success", text: "Registo guardado com sucesso!" });
      setForm({ date: today, entry: "", exit: "", location: "office", projectId: "", notes: "" });
    } catch { setMsg({ type: "error", text: "Erro ao guardar. Tente novamente." }); }
    setLoading(false);
  };
  const preview = form.entry && form.exit && toMins(form.exit) > toMins(form.entry) ? calcExtra(form.entry, form.exit) : null;
  return (
    <div>
      <div style={css.pageTitle}>Registar Horas</div>
      <div style={css.card}>
        {msg && <div style={css.alert(msg.type)}>{msg.text}</div>}
        <div style={css.grid(2)}>
          <div style={css.fg}><label style={css.label}>Data *</label><input style={css.input} type="date" value={form.date} onChange={e => setForm({ ...form, date: e.target.value })} /></div>
          <div style={css.fg}><label style={css.label}>Projeto *</label>
            <select style={css.select} value={form.projectId} onChange={e => setForm({ ...form, projectId: e.target.value })}>
              <option value="">Selecione um projeto</option>
              {active.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
            </select>
          </div>
          <div style={css.fg}><label style={css.label}>Hora de Entrada *</label><input style={css.input} type="time" value={form.entry} onChange={e => setForm({ ...form, entry: e.target.value })} /></div>
          <div style={css.fg}><label style={css.label}>Hora de Saída *</label><input style={css.input} type="time" value={form.exit} onChange={e => setForm({ ...form, exit: e.target.value })} /></div>
        </div>
        <div style={css.fg}><label style={css.label}>Local *</label>
          <div style={{ display: "flex", gap: 10 }}>
            {["office", "external"].map(l => <button key={l} style={css.tag(form.location === l)} onClick={() => setForm({ ...form, location: l })}>{l === "office" ? "🏢 Escritório" : "🏗 Externo"}</button>)}
          </div>
        </div>
        <div style={css.fg}><label style={css.label}>Notas</label><input style={css.input} value={form.notes} onChange={e => setForm({ ...form, notes: e.target.value })} placeholder="Observações..." /></div>
        {preview && (
          <div style={{ ...css.grid(3), marginBottom: 16 }}>
            <div style={{ ...css.statCard(S), borderRadius: 8, padding: "12px 20px" }}><div style={{ fontSize: 20, fontWeight: 700 }}>{toHrs(preview.total)}</div><div style={{ fontSize: 12, opacity: .8 }}>Total</div></div>
            <div style={{ ...css.statCard("#16a34a"), borderRadius: 8, padding: "12px 20px" }}><div style={{ fontSize: 20, fontWeight: 700 }}>{toHrs(preview.normal)}</div><div style={{ fontSize: 12, opacity: .8 }}>Normal</div></div>
            <div style={{ ...css.statCard(preview.extra > 0 ? P : "#9ca3af"), borderRadius: 8, padding: "12px 20px" }}><div style={{ fontSize: 20, fontWeight: 700 }}>{toHrs(preview.extra)}</div><div style={{ fontSize: 12, opacity: .8 }}>Extra</div></div>
          </div>
        )}
        <button style={css.btn("primary")} onClick={save} disabled={loading}>{loading ? "A guardar..." : "💾 Guardar Registo"}</button>
      </div>
    </div>
  );
}

