function AdminProjects({ projects }) {
  const [name, setName] = useState(""), [msg, setMsg] = useState(null);
  const [editing, setEditing] = useState(null); // { id, name }
  const [confirmDelete, setConfirmDelete] = useState(null); // project

  const add = async () => {
    if (!name.trim()) return;
    await addDoc(collection(db, "projects"), { name: name.trim(), status: "active", createdAt: serverTimestamp() });
    setName(""); setMsg({ type: "success", text: "Projeto criado!" }); setTimeout(() => setMsg(null), 2000);
  };

  const toggle = async p => {
    await updateDoc(doc(db, "projects", p.id), { status: p.status === "active" ? "archived" : "active" });
  };

  const saveEdit = async () => {
    if (!editing.name.trim()) return;
    await updateDoc(doc(db, "projects", editing.id), { name: editing.name.trim() });
    setEditing(null); setMsg({ type: "success", text: "Projeto atualizado!" }); setTimeout(() => setMsg(null), 2000);
  };

  const deleteProject = async p => {
    const { deleteDoc } = await import("firebase/firestore");
    await deleteDoc(doc(db, "projects", p.id));
    setConfirmDelete(null); setMsg({ type: "success", text: "Projeto removido!" }); setTimeout(() => setMsg(null), 2000);
  };

  return (
    <div>
      <div style={css.pageTitle}>Gestão de Projetos</div>

      {/* Modal de confirmação de remoção */}
      {confirmDelete && (
        <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.4)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 1000 }}>
          <div style={{ background: "#fff", borderRadius: 12, padding: 32, width: 360, boxShadow: "0 8px 32px rgba(0,0,0,.2)" }}>
            <div style={{ fontSize: 18, fontWeight: 700, marginBottom: 10 }}>Remover Projeto</div>
            <div style={{ fontSize: 14, color: GRAY, marginBottom: 24 }}>Tens a certeza que queres remover o projeto <b>"{confirmDelete.name}"</b>? Esta ação não pode ser desfeita.</div>
            <div style={{ display: "flex", gap: 10, justifyContent: "flex-end" }}>
              <button style={css.btn("")} onClick={() => setConfirmDelete(null)}>Cancelar</button>
              <button style={css.btn("primary")} onClick={() => deleteProject(confirmDelete)}>🗑 Remover</button>
            </div>
          </div>
        </div>
      )}

      <div style={css.card}>
        <div style={css.cardTitle}>Novo Projeto</div>
        {msg && <div style={css.alert(msg.type)}>{msg.text}</div>}
        <div style={{ display: "flex", gap: 10 }}>
          <input style={{ ...css.input, flex: 1 }} placeholder="Nome do projeto" value={name} onChange={e => setName(e.target.value)} onKeyDown={e => e.key === "Enter" && add()} />
          <button style={css.btn("primary")} onClick={add}>+ Adicionar</button>
        </div>
      </div>

      <div style={css.card}>
        <div style={css.cardTitle}>Projetos ({projects.length})</div>
        <table style={css.table}>
          <thead><tr>{["Nome", "Estado", "Ações"].map(h => <th key={h} style={css.th}>{h}</th>)}</tr></thead>
          <tbody>
            {projects.map(p => (
              <tr key={p.id}>
                <td style={css.td}>
                  {editing?.id === p.id
                    ? <div style={{ display: "flex", gap: 8 }}>
                        <input style={{ ...css.input, flex: 1 }} value={editing.name} onChange={e => setEditing({ ...editing, name: e.target.value })} onKeyDown={e => e.key === "Enter" && saveEdit()} autoFocus />
                        <button style={{ ...css.btn("primary"), padding: "6px 12px", fontSize: 13 }} onClick={saveEdit}>✓</button>
                        <button style={{ ...css.btn(""), padding: "6px 12px", fontSize: 13 }} onClick={() => setEditing(null)}>✕</button>
                      </div>
                    : <b>{p.name}</b>
                  }
                </td>
                <td style={css.td}><span style={css.badge(p.status === "active" ? "green" : "gray")}>{p.status === "active" ? "Ativo" : "Arquivado"}</span></td>
                <td style={{ ...css.td, display: "flex", gap: 8 }}>
                  <button style={{ ...css.btn(""), fontSize: 13, padding: "5px 12px" }} onClick={() => setEditing({ id: p.id, name: p.name })}>✏️ Editar</button>
                  <button style={{ ...css.btn(""), fontSize: 13, padding: "5px 12px" }} onClick={() => toggle(p)}>{p.status === "active" ? "📦 Arquivar" : "✅ Ativar"}</button>
                  <button style={{ ...css.btn(""), fontSize: 13, padding: "5px 12px", color: "#dc2626" }} onClick={() => setConfirmDelete(p)}>🗑 Remover</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

