                  return <tr key={r.id}><td style={css.td}>{r.date}</td><td style={css.td}>{r.entry}</td><td style={css.td}>{r.exit}</td><td style={css.td}>{toHrs(normal)}</td><td style={css.td}><span style={{ color: extra > 0 ? P : "#16a34a", fontWeight: 600 }}>{toHrs(extra)}</span></td><td style={css.td}><span style={css.badge(r.location === "external" ? "blue" : "green")}>{r.location === "external" ? "Externo" : "Escritório"}</span></td><td style={css.td}>{projects.find(p => p.id === r.projectId)?.name || "—"}</td></tr>;
                })}
              </tbody>
            </table>
            <button style={css.btn("primary")} onClick={() => generatePDF(emp, filtered, projects, selMonth, selYear)}>🖨 Imprimir / Exportar PDF</button>
          </>
        ) : <div style={{ color: GRAY, fontSize: 14, marginTop: 8 }}>Nenhum registo para este período.</div>}
      </div>
    </div>
  );
}

// ─── MAIN APP ─────────────────────────────────────────────────────────────────
export default function App() {
  const [authUser, setAuthUser] = useState(undefined);
  const [userDoc, setUserDoc] = useState(null);
  const [page, setPage] = useState("dashboard");
  const [records, setRecords] = useState([]);
  const [projects, setProjects] = useState([]);
  const [allUsers, setAllUsers] = useState([]);

  // Auth listener
  useEffect(() => {
    return onAuthStateChanged(auth, async u => {
      if (u) {
        const snap = await getDoc(doc(db, "users", u.uid));
        setUserDoc(snap.exists() ? { uid: u.uid, ...snap.data() } : { uid: u.uid, name: u.email, role: "employee" });
        setAuthUser(u);
      } else { setAuthUser(null); setUserDoc(null); }
    });
  }, []);

  // Projetos em tempo real
  useEffect(() => {
    if (!authUser) return;
    return onSnapshot(collection(db, "projects"), snap => {
      setProjects(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
  }, [authUser]);

  // Registos em tempo real
  useEffect(() => {
    if (!authUser || !userDoc) return;
    const q = userDoc.role === "admin"
      ? collection(db, "records")
      : query(collection(db, "records"), where("userId", "==", authUser.uid));
    return onSnapshot(q, snap => {
      setRecords(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
  }, [authUser, userDoc]);

  // Todos os utilizadores (só admin)
  useEffect(() => {
    if (!userDoc || userDoc.role !== "admin") return;
    return onSnapshot(collection(db, "users"), snap => {
      setAllUsers(snap.docs.map(d => ({ uid: d.id, ...d.data() })));
    });
  }, [userDoc]);

  if (authUser === undefined) return <Spinner />;
  if (!authUser) return <LoginPage />;
  if (!userDoc) return <Spinner />;

  const isAdmin = userDoc.role === "admin";
  const adminNav = [
    { id: "dashboard", label: "Dashboard", icon: "📊" },
    { id: "records", label: "Registos", icon: "📋" },
    { id: "projects", label: "Projetos", icon: "🏗" },
    { id: "reports", label: "Relatórios", icon: "📄" },
  ];
  const empNav = [
    { id: "dashboard", label: "Início", icon: "🏠" },
    { id: "register", label: "Registar Horas", icon: "⏱" },
    { id: "history", label: "Meu Histórico", icon: "📋" },
  ];
  const nav = isAdmin ? adminNav : empNav;

  const renderPage = () => {
    if (isAdmin) {
      if (page === "dashboard") return <AdminDashboard allRecords={records} projects={projects} allUsers={allUsers} />;
      if (page === "records") return <AdminRecords allRecords={records} projects={projects} allUsers={allUsers} />;
      if (page === "projects") return <AdminProjects projects={projects} />;
      if (page === "reports") return <AdminReports allRecords={records} projects={projects} allUsers={allUsers} />;
    } else {
      if (page === "dashboard") return <EmpDashboard user={userDoc} records={records} projects={projects} />;
      if (page === "register") return <EmpRegister user={userDoc} projects={projects} />;
      if (page === "history") return <EmpHistory records={records} projects={projects} />;
    }
  };

  return (
    <div style={css.app}>
      <header style={css.header}>
        <div style={css.logo}>⏱ TimeTrack</div>
        <div style={{ display: "flex", alignItems: "center", gap: 10, fontSize: 14 }}>
          <div style={css.avatar}>{initials(userDoc.name)}</div>
          <span>{userDoc.name}</span>
          <button style={css.logoutBtn} onClick={() => signOut(auth)}>Sair</button>
        </div>
      </header>
      <div style={css.layout}>
        <aside style={css.sidebar}>
          {nav.map(n => <div key={n.id} style={css.navItem(page === n.id)} onClick={() => setPage(n.id)}><span>{n.icon}</span>{n.label}</div>)}
          <div style={{ marginTop: "auto", padding: "20px 20px 8px" }}>
            <span style={css.badge(isAdmin ? "red" : "blue")}>{isAdmin ? "Administrador" : "Funcionário"}</span>
          </div>
        </aside>
        <main style={css.main}>{renderPage()}</main>
      </div>
    </div>
  );
}
